// "RTI View" story card:
//  • Front: digital short story (photo, headline, ~60-word summary) with newspaper masthead strip
//  • Back:  auto-generated newspaper clipping (tap "📰 క్లిప్పింగ్" to flip)
//  • Verified reporter badge with years of experience
//  • Public-issue tracker (Reported → Officials informed → Action taken) for RTI / civic stories
//  • Integrated star rating
import { useState } from "react";
import { StarRating } from "@/features/rating/StarRating";
import "./feed.css";

export type IssueStatus = "reported" | "informed" | "action";

export interface Story {
  id: string;
  headline: string;
  summary: string; // ≤ 60 words
  imageUrl?: string;
  clippingUrl?: string; // the JPG generated by app
  place: string; // real dateline place, e.g. "గోదావరిఖని"
  district: string;
  category: string; // రాజకీయం, ప్రజా సమస్య, భక్తి, క్రీడలు …
  publishedAt: string;
  reporter: { name: string; avatarUrl?: string; verified: boolean; yearsExp?: number };
  issue?: { status: IssueStatus; note?: string };
  stats?: { views: number; likes: number; comments?: number };
}

const STEPS: { key: IssueStatus; te: string }[] = [
  { key: "reported", te: "ఫిర్యాదు" },
  { key: "informed", te: "అధికారుల దృష్టికి" },
  { key: "action", te: "చర్య తీసుకున్నారు" },
];

const timeAgoTe = (iso: string) => {
  const m = Math.max(1, Math.round((Date.now() - new Date(iso).getTime()) / 60000));
  if (m < 60) return `${m} నిమిషాల క్రితం`;
  const h = Math.round(m / 60);
  return h < 24 ? `${h} గంటల క్రితం` : `${Math.round(h / 24)} రోజుల క్రితం`;
};

export function StoryCard({
  story,
  index,
  total,
  onShare,
  onComment,
  onLike,
  isLiked,
}: {
  story: Story;
  index: number;
  total: number;
  onShare?: (story: Story, isFlipped: boolean) => void;
  onComment?: (id: string) => void;
  onLike?: (id: string) => void;
  isLiked?: boolean;
}) {
  const [flipped, setFlipped] = useState(false);
  const s = story;

  const handleShare = async () => {
    if (onShare) {
      onShare(s, flipped);
      return;
    }
    const text = `${s.headline}\n\n${s.summary}\n\n— RTI Express Spot News 24x7`;
    try {
      if (flipped && s.clippingUrl && navigator.canShare) {
        const blob = await (await fetch(s.clippingUrl)).blob();
        const file = new File([blob], `RTI_${s.id}.jpg`, { type: blob.type || "image/jpeg" });
        if (navigator.canShare({ files: [file] })) return navigator.share({ files: [file], text: s.headline });
      }
      if (navigator.share) return navigator.share({ text });
    } catch {
      /* user cancelled */
    }
    window.open(`https://wa.me/?text=${encodeURIComponent(text)}`, "_blank");
  };

  const stepIdx = s.issue ? STEPS.findIndex((x) => x.key === s.issue!.status) : -1;

  return (
    <section className="story-slide">
      <div className={`flip ${flipped ? "is-flipped" : ""}`}>
        {/* ---------- FRONT: digital story ---------- */}
        <article className="face front">
          <div className="masthead">
            <span className="mh-brand">RTI EXPRESS</span>
            <span className="mh-meta">
              {new Date(s.publishedAt).toLocaleDateString("te-IN", { day: "numeric", month: "short" })} · {s.place}
            </span>
            <span className="mh-count">
              {index + 1}/{total}
            </span>
          </div>

          <div className="photo" style={s.imageUrl ? { backgroundImage: `url(${s.imageUrl})` } : undefined}>
            {!s.imageUrl && (
              <div className="auto-cover">
                <span>{s.place}</span>
              </div>
            )}
            <span className="chip cat">{s.category || "తాజా వార్త"}</span>
          </div>

          <div className="body">
            <h2 className="headline">{s.headline}</h2>
            <p className="summary">{s.summary}</p>

            {s.issue && (
              <div className="tracker" aria-label="Public issue status">
                {STEPS.map((st, i) => (
                  <div key={st.key} className={`step ${i <= stepIdx ? "done" : ""}`}>
                    <span className="dot">{i <= stepIdx ? "✓" : i + 1}</span>
                    <span className="lbl">{st.te}</span>
                  </div>
                ))}
              </div>
            )}

            <div className="reporter">
              <div
                className="avatar"
                style={s.reporter.avatarUrl ? { backgroundImage: `url(${s.reporter.avatarUrl})` } : undefined}
              >
                {!s.reporter.avatarUrl && (s.reporter.name ? s.reporter.name.charAt(0) : "R")}
              </div>
              <div className="r-text">
                <div className="r-name">
                  {s.reporter.name}{" "}
                  {s.reporter.verified && (
                    <span className="tick" title="Verified reporter">
                      ✔
                    </span>
                  )}
                </div>
                <div className="r-sub">
                  {s.reporter.verified ? "వెరిఫైడ్ రిపోర్టర్" : "రిపోర్టర్"}
                  {s.reporter.yearsExp ? ` · ${s.reporter.yearsExp}+ ఏళ్ల అనుభవం` : ""} · {timeAgoTe(s.publishedAt)}
                </div>
              </div>
            </div>

            {/* Inline Star Rating for Reporter */}
            <div className="mt-1 pt-1 border-t border-gray-100">
              <StarRating postId={s.id} reporterName={s.reporter.name} />
            </div>
          </div>
        </article>

        {/* ---------- BACK: newspaper clipping ---------- */}
        <article className="face back">
          <div className="masthead paper">
            <span className="mh-brand">📰 పేపర్ క్లిప్పింగ్</span>
            <span className="mh-meta">{s.place}</span>
          </div>
          {s.clippingUrl ? (
            <img className="clip-img" src={s.clippingUrl} alt={s.headline} />
          ) : (
            <div className="clip-missing">క్లిప్పింగ్ సిద్ధమవుతోంది…</div>
          )}
        </article>
      </div>

      {/* ---------- action bar (same for both faces) ---------- */}
      <nav className="actions">
        <button
          className="act"
          onClick={() => onLike?.(s.id)}
          style={{ color: isLiked ? "#3b82f6" : "#ffffff" }}
        >
          {isLiked ? "❤️" : "♡"} {s.stats?.likes ?? ""}
        </button>
        <button className="act" onClick={() => onComment?.(s.id)}>
          💬 {s.stats?.comments ?? ""}
        </button>
        <button className="act flip-btn" onClick={() => setFlipped(!flipped)}>
          {flipped ? "📱 వార్త" : "📰 క్లిప్పింగ్"}
        </button>
        <button className="act wa" onClick={handleShare}>
          షేర్
        </button>
      </nav>
    </section>
  );
}
